import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { useFormik } from "formik";
import { useDispatch, useSelector } from "react-redux";
import { useStateContext } from "../../../../contexts/ContextProvider";
import { Link, Navigate, useNavigate } from "react-router-dom";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import CustomForm from "../../../../components/forms/CustomForm";
import CustomFormItem from "../../../../components/forms/CustomFormItem";
import CustomInput from "../../../../components/forms/CustomInput";
import CustomSelectReactSelect from "../../../../components/forms/CustomSelectReactSelect";
import CustomDatePicker from "../../../../components/forms/CustomDatePicker";
import CustomCheckBox from "../../../../components/forms/CustomCheckBox";
import FileUploader from "../../../../components/FileUploader";
import useApi from "../../../../hooks/useApi";
import "react-datepicker/dist/react-datepicker.css";
import Loading from "../../../../components/Loading";
import countriesApi from "../../../../api/countriesApi";
import countiesApi from "../../../../api/countiesApi";
import { Button } from "@heroui/react";
import registerApi from "../../../../api/registerApi";
import saccosApi from "../../../../api/saccos/saccosApi";
import { CustomSelectAsyncSelect } from "../../../../components";
import preparationsApi from "../../../../api/drugs/preparationsApi";
import { el } from "@faker-js/faker";

const MemberAccountForm = () => {
  const navigate = useNavigate();
  const moment = require("moment");
  const dispatch = useDispatch();
  const { currentColor, loggedInUser } = useStateContext();
  const user = useSelector((state) => state.Auth.user);
  // const errors = useSelector((state) => state.Auth.errors);

  const [errors, seterrors] = useState([]);
  const loading = useSelector((state) => state.Auth.loading);
  const created = useSelector((state) => state.Auth.created);
  const [signatories, setSignatories] = useState([])
  console.log("user1", loggedInUser);
  const formik = useFormik({
    initialValues: {
    
      signatories: [],
      accountAdministrator: "",
      accountType: "",
      accountNature: "",
    },

    validationSchema: Yup.object({

      signatories: Yup.array().min(1).max(2).label("Signatories"),
      accountAdministrator: Yup.object().required().label("County"),
  
      accountNature: Yup.object().required().label("Account Type"),
      accountType: Yup.object().required().label("Account Nature"),


    }),

    onSubmit: (values) => {
   
      let signatoriesStr=""

      console.log("VALZ", values);


//       data.append("accountType", values.accountType.value);
//       data.append("accountNature", values.accountNature.value);
//       data.append("accountAdministrator", values.accountAdministrator.value);

//       if(values.signatories.length){
//         values.signatories.map((x) => {
//          signatoriesStr+=x.value+","
//         });
//       }
// data.append("signatories", signatoriesStr);

const data = {
  action: "CreateMemberAccount",
  accountType: values.accountType.value,
  accountNature: values.accountNature.value,
  accountAdministrator: values.accountAdministrator.value,
  signatories: values.signatories.map((x) => x.value).join(","),      
};


      createMemberAccount(data);
      // dispatch(registerUser(data));
    },
  });

  useEffect(() => {
    if (created && user) {
      navigate("/login");
    }
  }, [created, user]);



  //Register

  const createMemberAccountApi = useApi(saccosApi.saccoStaffAction);

  const createMemberAccount = async (data) => {
    await createMemberAccountApi.request(data);

  };
  useEffect(() => {
    if (createMemberAccountApi.data && createMemberAccountApi.data.response_code === 1) {
      toast.error(createMemberAccountApi.response_message);
    }
    if (createMemberAccountApi.data && createMemberAccountApi.data.response_code === 0) {
      toast.success(createMemberAccountApi.response_message);
      navigate("/saccos/members/accounts");
    }
    if (createMemberAccountApi.data && createMemberAccountApi.data.errors && createMemberAccountApi.data.errors.length) {
      seterrors(createMemberAccountApi.data.errors);
      createMemberAccountApi.data.errors.map((x) => {
        toast.error(x);
      });
    }

    console.log("doRegisterApi.data", createMemberAccountApi.data);
  }, [createMemberAccountApi.data]);









  //Remove file uploader selected image




  const searchSaccoMembersApi = useApi(saccosApi.saccoStaffAction);

  const searchSaccoMembers = async (data) => {
    await searchSaccoMembersApi.request(data);
  };

  const [saccoMembers, setSaccoMembers] = useState();

  useEffect(() => {
    if (searchSaccoMembersApi.data) {
      if (searchSaccoMembersApi.data.length) {
        setSaccoMembers(searchSaccoMembersApi.data);
      }
    }
    console.log("Sacco Members", searchSaccoMembersApi.data);
  }, [searchSaccoMembersApi.data]);

  const loadSaccoMemberOptions = async (inputText = "", callback) => {
    searchSaccoMembers({
      action: "SearchSaccoMemberAccounts",
      searchQuery: inputText,
    });

    callback(saccoMembers.map((i) => ({ label: `${i.firstName} ${i.lastName}`, value: i.id })));
  };

  return (<div className="mt-16 md:mt-2 grid grid-cols-1 md:grid-cols-12 bg-gray-50 py-5">
    <div className="col-span-2 hidden md:block"></div>
    <div className="col-span-8  bg-gray-100 items-center justify-center">
      <ToastContainer theme="colored" position="bottom-center" />
      <p className='font-bold text-center text-lg'>Create Member Account</p>
      <CustomForm
        layout="vertical"
        handleFinish={formik.handleSubmit}
        className="items-center w-full"
      >
        <div className="w-full grid grid-cols-2 mt- gap-1 px-5">


          <CustomFormItem
            touched={formik.touched.accountAdministrator}
            error={formik.errors.accountAdministrator}
          >
            <CustomSelectAsyncSelect
              className="h-5"
              size="large"
              name="accountAdministrator"

              placeholder="Search  administrator by phone number"
              isClearable
              value={formik.values.accountAdministrator}
              onChange={(value) => formik.setFieldValue("accountAdministrator", value)}
              loadOptions={loadSaccoMemberOptions}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.signatories}
            error={formik.errors.signatories}
          >
            <CustomSelectAsyncSelect
              className="h-5"
              size="large"
              name="signatories"
              isMulti={true}
              placeholder="Search signatories by phone number"
              isClearable
              value={formik.values.signatories}
              onChange={(value) => formik.setFieldValue("signatories", value)}
              loadOptions={loadSaccoMemberOptions}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.accountNature}
            error={formik.errors.accountNature}
          >
            <CustomSelectReactSelect
              name="accountNature"
              id="accountNature"
              label="Account Nature"
              size="large"
              onChange={(e) => formik.setFieldValue("accountNature", e)}
              value={formik.values.accountNature}
              placeholder="Select account nature"
              options={[
                { value: "GROUP", label: "GROUP" },
                { value: "INDIVIDUAL", label: "INDIVIDUAL" },
              ]}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.accountType}
            error={formik.errors.accountType}
          >
            <CustomSelectReactSelect
              name="accountType"
              id="accountType"
              label="Account Type"
              size="large"
              onChange={(e) => formik.setFieldValue("accountType", e)}
              value={formik.values.accountType}
              placeholder="Select account type"
              options={[
                { value: "FIXED DEPOSIT", label: "FIXED DEPOSIT" },
                { value: "SAVINGS ACCOUNT", label: "SAVINGS ACCOUNT" },
                { value: "SHARES DEPOSIT", label: "SHARES DEPOSIT" },
                { value: "TERM DEPOSIT", label: "TERM DEPOSIT" },
              ]}
            />
          </CustomFormItem>

        </div>

        <div className="w-full flex items-center mt-2 justify-center ">
          <Button className="w-36 rounded-md" color="primary" type="submit">
            Submit
          </Button>
        </div>
      </CustomForm>

    </div>
    <div className="col-span-2 hidden md:block"></div>
  </div>);
};

export default MemberAccountForm;
